const s = $getWorkflowStaticData('global');
let b = $input.first().json.body;
if (typeof b === 'string') b = JSON.parse(b.replace(/\bNaN\b/g, 'null'));
s.list = (b && b.list) || [];
s.updated = new Date().toISOString();
return [{ json: { ok: true, count: s.list.length } }];

const s = $getWorkflowStaticData('global');
const list = (s.list || []).slice();
const G = '#16a34a', R = '#dc2626', N = '#6b7280', B = '#2563eb';
const col = x => /ABOVE/.test(x) ? G : /BELOW/.test(x) ? R : N;
const f = v => (v === null || v === undefined || Number.isNaN(v)) ? '-' : v;
const rank = x => /PDH|PDL/.test(x) ? 0 : /PMH|PML/.test(x) ? 1 : 2;
list.sort((a, b) => rank(a.signal) - rank(b.signal));
const et = s.updated ? new Date(s.updated).toLocaleString('en-US', { timeZone: 'America/New_York' }) + ' ET' : 'no data yet';
const cell = (txt, bg) => `<td style="background:${bg};color:#fff">${txt}</td>`;
const vote = ch => ch === 'B' ? cell('BULL', G) : ch === 'S' ? cell('BEAR', R) : cell('-', N);
const names = ['DMI', 'Aroon', 'MACD x', 'MACD 0', 'RSI 50', 'Chaikin', 'Force', 'TRIX', 'OBV', '20 EMA'];
const rows = list.map(r => {
  const v = (r.votes || '----------').padEnd(10, '-');
  const bull = [...v].filter(c => c === 'B').length, bear = [...v].filter(c => c === 'S').length;
  const adx = (r.adx === null || r.adx === undefined) ? cell('-', N) : cell(Number(r.adx).toFixed(1) + (r.adx >= 20 ? ' TREND' : ' RANGE'), r.adx >= 20 ? B : N);
  const vbg = bull >= 7 ? G : bear >= 7 ? R : N;
  const kc = r.kc === 1 ? cell('UP', G) : r.kc === -1 ? cell('DOWN', R) : cell('no', N);
  return `<tr><td><b>${r.t}</b></td><td>${f(r.price)}</td>${cell(r.signal, col(r.signal))}${cell(r.side, col(r.side))}${adx}${[...v].slice(0, 10).map(vote).join('')}${cell(bull + ' / ' + bear, vbg)}${kc}</tr>`;
}).join('');
const head = ['Ticker', 'Price', 'Level', 'VWAP', 'ADX', ...names, 'Bull/Bear', 'Keltner'].map(h => `<th>${h}</th>`).join('');
const html = `<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><meta http-equiv=refresh content=60><title>CC Levels</title><style>body{font-family:sans-serif;background:#0f172a;color:#e2e8f0;padding:6px;font-size:11px;margin:0}h2{font-size:13px;margin:2px 0}p{margin:2px 0 4px;font-size:10px}table{border-collapse:collapse;width:100%}td,th{padding:2px 4px;border-bottom:1px solid #334155;text-align:center;white-space:nowrap}th{color:#94a3b8;font-weight:600}.w{overflow-x:auto}</style></head><body><h2>Key Levels + Confluence <span style="font-size:10px;color:#94a3b8">levels v4</span></h2><p>Updated: ${et} (page refreshes every 60s)</p><div class=w><table><tr>${head}</tr>${rows || '<tr><td colspan=18>No data yet</td></tr>'}</table></div></body></html>`;
return [{ json: { html } }];
